function renderResults(){const a=analysis;$('results').hidden=false;$('summary').textContent=`${a.changes.length} Vorschläge · ${a.warnings.length} Prüfhinweise · keine Änderung ungeprüft übernommen`;$('warnings').innerHTML=a.warnings.map(w=>`<div class="warning">⚠ ${esc(w)}</div>`).join('');$('changes').innerHTML=a.changes.map((c,i)=>`<div class="change"><label><input type="checkbox" data-change="${i}"> Vorschlag ${i+1} bestätigen · ${c.kind==='typography'?'Guillemets / Auslassung':c.kind.startsWith('bib')?'Literaturverzeichnis':c.kind==='footnote'?'Fussnote':'Textnachweis'}</label>${!c.kind.startsWith('bib')&&c.kind!=='typography'?`<label>Zitatform<select data-paraphrase="${i}"><option value="" ${c.paraphrase===null?'selected':''}>Zitatform bitte festlegen</option><option value="direct" ${c.paraphrase===false?'selected':''}>Wörtlich · exakter Wortlaut</option><option value="indirect" ${c.paraphrase?'selected':''}>Sinngemäss · eigene Formulierung</option></select></label>`:''}<div class="quote-check"></div><p class="before">${esc(c.before)}</p><p>→ ${rich(c.after)}${noteMode()&&c.kind==='citation'?' <small>(als echte Fussnote)</small>':''}</p><small>${c.kind==='typography'?esc(c.reason)+' · Kontext: '+esc(c.context):'Zitatform ausdrücklich prüfen: Wörtlich = exakter Wortlaut in «Guillemets»; sinngemäss = eigene Worte ohne Zitat-Guillemets; bei der geisteswissenschaftlichen Vorlage mit vgl. Quelle, Seitenzahl und Zitatgrenzen kontrollieren.'}</small></div>`).join('');$('export').disabled=true;document.querySelectorAll('[data-change]').forEach(e=>e.onchange=refreshSelected);document.querySelectorAll('[data-paraphrase]').forEach(e=>e.onchange=()=>{const i=+e.dataset.paraphrase;analysis.changes[i].paraphrase=e.value===''?null:e.value==='indirect';document.querySelector(`[data-change="${i}"]`).checked=false;refreshSelected()});refreshSelected()}
function refreshSelected(){if(!analysis)return;const seen=new Set();for(const [i,c] of analysis.changes.entries()){if(c.kind.startsWith('bib')||c.kind==='typography')continue;const approval=document.querySelector(`[data-change="${i}"]`);approval.disabled=c.paraphrase===null;if(approval.disabled)approval.checked=false;c.after=citationValue(c,seen.has(c.source));if(document.querySelector(`[data-change="${i}"]:checked`))seen.add(c.source);const card=document.querySelector(`[data-change="${i}"]`).closest('.change');const context=text(c.kind==='footnote'?c.ref.parentNode.parentNode:c.p);const hasQuotes=/[«»‹›„“”"]/.test(context);card.querySelector('.quote-check').textContent=c.paraphrase===false&&!hasQuotes?'⚠ Wörtlich gewählt: Im zugehörigen Absatz sind keine Zitatzeichen erkennbar. Zitatbereich und Guillemets manuell ergänzen.':c.paraphrase===true&&hasQuotes?'⚠ Sinngemäss gewählt: Der Absatz enthält Zitatzeichen. Prüfen, ob sie zu diesem Nachweis oder zu einem anderen wörtlichen Zitat gehören.':'';card.querySelectorAll('p')[1].innerHTML='→ '+rich(c.after)+(c.paraphrase===null?' <small>— Zitatform noch offen</small>':c.paraphrase?' <small>— Sinngemäss: eventuell vorhandene Zitat-Guillemets im zugehörigen Text prüfen; keine automatische Entfernung.</small>':' <small>— Wörtlich: Wortlaut und zugehörige Guillemets im Text prüfen.</small>')+(noteMode()&&c.kind==='citation'?' <small>(als echte Fussnote)</small>':'')} $('export').disabled=!document.querySelector('[data-change]:checked');}
