function replaceRange(p,start,end,replacement){const ts=nodes(p,'t');let pos=0,first,last,fs,le;for(const t of ts){const len=t.textContent.length;if(first===undefined&&start<pos+len){first=t;fs=start-pos}if(end>pos&&end<=pos+len){last=t;le=end-pos;break}pos+=len}if(!first||!last)throw Error('Textbereich konnte nicht sicher ersetzt werden.');const fr=first.parentNode,lr=last.parentNode,tail=last.textContent.slice(le);const tailRun=lr.cloneNode(false);const pr=nodes(lr,'rPr')[0];if(pr)tailRun.appendChild(pr.cloneNode(true));const tt=element(p.ownerDocument,'t',{},tail);tt.setAttributeNS('http://www.w3.org/XML/1998/namespace','xml:space','preserve');tailRun.appendChild(tt);const anchor=lr.nextSibling;first.textContent=first.textContent.slice(0,fs);if(fr!==lr){let n=fr.nextSibling;while(n){const next=n.nextSibling;p.removeChild(n);if(n===lr)break;n=next}}p.insertBefore(replacement,anchor);if(tail)p.insertBefore(tailRun,anchor)}
